package store

import (
	"context"
	"fmt"
)

// Journeys project delivery attempts and human decisions from stored runs.
// These lookups support batched outcome reads; SDK checkpoint inspection owns
// the evidence used by the journey projection.

// journeyOutcomePrefix namespaces journey-grain Outcome Decisions, mirroring the
// run-grain `outcome-<runId>` convention. Journey keys are generated by
// journey.Key and are path-safe by construction (`j-` + hex), and run ids always
// start with a timestamp, so `outcome-journey-<key>` can never collide with an
// `outcome-<runId>` id.
const journeyOutcomePrefix = outcomeIDPrefix + "journey-"

// JourneyOutcomeDecisionID names legacy journey outcomes for existing reads.
// New decisions use JourneyAttemptOutcomeDecisionID so later attempts can receive
// their own outcome without overwriting an earlier decision.
func JourneyOutcomeDecisionID(key string) string { return journeyOutcomePrefix + key }

// JourneyAttemptOutcomeDecisionID identifies one immutable journey decision at
// the current attempt. Journey keys contain no colon, making this separator
// unambiguous while keeping legacy journey and run outcome IDs distinct.
func JourneyAttemptOutcomeDecisionID(key, runID string) string {
	return JourneyOutcomeDecisionID(key) + ":" + runID
}

// JourneyRunLimit bounds the run window a journey projection is derived over.
//
// Derived-only has a price: the grouping key is computed in Go (it hashes a
// delivery identity), so it cannot be a GROUP BY, and the newest-attempt rule
// needs a journey's whole attempt list — not just its undecided runs. So we read
// a window of recent top-level runs and group them here. 400 is far more history
// than a local-first instance shows in one sitting, and the query is one indexed
// scan on (project, updated_at DESC).
const JourneyRunLimit = 400

// DecisionsByIDs fetches decision rows by primary key, returning only the ids
// that exist. It is the batched form of GetDecision, for surfaces that must ask
// "which of these many things have been decided?" without one query per thing —
// the journey list asks it twice, once for journey outcomes and once for the
// run-grain outcomes attached to individual attempts.
func (s *Store) DecisionsByIDs(ctx context.Context, ids []string) (map[string]Decision, error) {
	out := map[string]Decision{}
	if len(ids) == 0 {
		return out, nil
	}
	rows, err := s.Pool.Query(ctx, `SELECT `+decisionCols+` FROM decisions WHERE id = ANY($1)`, ids)
	if err != nil {
		return nil, fmt.Errorf("decisions by ids: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		d, err := scanDecision(rows)
		if err != nil {
			return nil, err
		}
		out[d.ID] = d
	}
	return out, rows.Err()
}
